// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        // Bound amounts to avoid overflow in test helper calculations, but allow values that can trigger overflow in buggy contract
        amount1 = bound(amount1, 0, type(uint256).max / 2);
        amount2 = bound(amount2, 0, type(uint256).max / 2);

        // Two different actors to demonstrate the property
        address alice = address(0x1);
        address bob = address(0x2);

        // Fund and call Put for alice
        vm.deal(alice, amount1);
        vm.prank(alice);
        c.Put{value: amount1}(0);

        // Fund and call Put for bob
        vm.deal(bob, amount2);
        vm.prank(bob);
        c.Put{value: amount2}(0);

        // Property: sum of all account balances equals total ETH sent to contract
        uint256 totalAcc = c.Acc(alice).balance + c.Acc(bob).balance;
        assertTrue(totalAcc == address(c).balance);
    }
}

