pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialBalance, uint256 addedValue, address actor) public {
        // initialBalance and addedValue must be such that the reference call doesn't overflow,
        // but we don't bound them heavily to keep the fuzzer exploring.
        vm.assume(initialBalance + addedValue >= initialBalance); // reference overflow check would pass
        // Ensure actor is not a precompile to avoid false reverts on low-level calls
        vm.assume(actor != address(this) && uint160(actor) > 10);
        // Set an unlockTime far in the future so Collect requirements won't interfere (not called)
        vm.deal(actor, addedValue);
        // Directly set the initial balance using a legacy trick: deploy a helper that calls Put with initialBalance first
        // Since we cannot call private storage directly, we first execute a Put to set initial balance and unlockTime
        vm.prank(actor);
        c.Put{value: initialBalance}(type(uint256).max); // unlockTime = max ensures Collect blocked
        uint256 balanceBefore = c.Acc(actor).balance;
        // Now the actual Put call whose property we check
        vm.prank(actor);
        c.Put{value: addedValue}(type(uint256).max);
        uint256 balanceAfter = c.Acc(actor).balance;
        assertTrue(balanceAfter == balanceBefore + addedValue);
    }
}

