pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint96 msgValue, uint48 unlockTime, address pranker) public {
        // Bound to keep in admissible domain (msgValue small enough to not overflow uint balance)
        uint256 value = uint256(msgValue);
        uint256 time = uint256(unlockTime);
        vm.assume(pranker != address(0) && pranker != address(c) && pranker != address(this));

        // Record current Log History length before Put
        (address logAddr) = address(c).call(abi.encodeWithSignature("LogFile()"));
        (bool succ, bytes memory data) = logAddr.call(abi.encodeWithSignature("History(uint256)", 0));
        // We need length; call the auto-generated getter for public array length?
        // The public array History in Log has a generated getter History(uint256) that reverts on index out-of-bounds.
        // We can get length by reading the slot? No, must use public surface. Use try/catch to find length.
        // After all calls, use try/catch to count elements. Simpler: measure History length before and after using try/catch
        // Iterate in a loop: but we can't loop in fuzz without risking gas. Instead, use a helper: call Log.History length?
        // The public state variable "History" is dynamic array; its getter takes (uint256 index) and returns Message.
        // There is NO length getter. Need to work around: we can use assembly to read Log's storage slot for array length.
        // Allowed: only public/external surface. So we cannot read array length.
        // So need a different assertion: Check the Log's LastMsg was updated.
        // The LastMsg is public; we can call LogFile.LastMsg() which returns (address,string,uint256,uint256).
        // The bug removes AddMessage call, so LastMsg is not updated after Put.
        // Rule: After a Put, the LastMsg.Sender must equal the Put caller.
        // So we assert that LastMsg.Sender == pranker.

        vm.deal(pranker, value);
        vm.prank(pranker);
        c.Put{value: value}(time);

        // Read LastMsg from the Log contract attached to c
        // The C contract has public state variable LogFile of type Log. So c.LogFile() returns address.
        Log logInst = c.LogFile();
        (address sender,,,) = logInst.LastMsg();
        assertTrue(sender == pranker);
    }
}

