pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint32 unlockTimeDelay) public {
        // 1. Restrict to admissible domain: amount > 0 and at least MinSum, delay positive
        vm.assume(amount >= c.MinSum());
        vm.assume(amount > 0);
        vm.assume(unlockTimeDelay > 0);
        vm.assume(unlockTimeDelay <= type(uint32).max - block.timestamp);
        uint256 unlockTime = block.timestamp + unlockTimeDelay;

        // 2. Setup: fund the caller, put funds with unlock time
        address user = address(0x1234);
        vm.deal(user, amount);
        vm.prank(user);
        c.Put{value: amount}(unlockTime);

        // Warp to before unlock time
        uint256 beforeUnlock = unlockTime - 1;
        vm.warp(beforeUnlock);

        // Try to collect
        vm.prank(user);
        bool ok;
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // 3. Assert: reference cannot collect before unlock time (ok must be false)
        assertTrue(!ok);
    }
}

