        try c.Collect(amount) {
            uint256 balanceAfter = c.Acc(actor).balance;
            // if collect succeeded, balance must have decreased by exactly amount
            assertTrue(balanceAfter == balanceBefore - amount);
        } catch {
            // if collect reverted, balance must be unchanged
            assertTrue(c.Acc(actor).balance == balanceBefore);
        }
    }
}

